<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Order;
use DateTimeImmutable; use InvalidArgumentException;
final class OrderBacklogInput { private string $from;private string $to;private string $group;private ?int $customer;private ?int $seller;private ?int $status;private int $limit;
public static function fromArguments(array $a):self{$x=new self;$x->from=(string)$a['date_from'];$x->to=(string)$a['date_to'];$x->group=(string)$a['group_by'];$x->customer=isset($a['customer_id'])?(int)$a['customer_id']:null;$x->seller=isset($a['seller_internal_id'])?(int)$a['seller_internal_id']:null;$x->status=isset($a['status'])?(int)$a['status']:null;$x->limit=isset($a['limit'])?(int)$a['limit']:20;$x->check();return $x;}
public function from():string{return $this->from;}public function to():string{return $this->to;}public function group():string{return $this->group;}public function customer():?int{return $this->customer;}public function seller():?int{return $this->seller;}public function status():?int{return $this->status;}public function limit():int{return $this->limit;}
private function check():void{$f=self::date($this->from);$t=self::date($this->to);if($f>$t)throw new InvalidArgumentException('A data inicial não pode ser posterior à data final.');$days=(int)$f->diff($t)->format('%a')+1;if($this->group==='day'&&$days>90)throw new InvalidArgumentException('O agrupamento diário aceita no máximo 90 dias. Não divida um período maior em consultas sequenciais; peça ao usuário um único recorte de até 90 dias.');$historical=in_array($this->group,['month','customer','seller_internal','status'],true);if($historical&&$t>$f->modify('+5 years'))throw new InvalidArgumentException('Resumos históricos aceitam no máximo 5 anos. Não divida um período maior em consultas sequenciais; peça ao usuário um único recorte de até 5 anos.');if(!$historical&&$t>$f->modify('+1 year'))throw new InvalidArgumentException('Agrupamentos semanais e listagens de documentos aceitam no máximo 12 meses. Não divida um período maior em consultas sequenciais; peça ao usuário um único recorte de até 12 meses.');}
private static function date(string $v):DateTimeImmutable{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();if($d===false||(is_array($e)&&($e['warning_count']>0||$e['error_count']>0)))throw new InvalidArgumentException('Informe datas válidas no formato AAAA-MM-DD.');return $d;}}
